  CONSTRAINT ck_ad_frequency_cap_some_cap CHECK (max_impressions IS NOT NULL OR max_clicks IS NOT NULL),
  CONSTRAINT ck_ad_frequency_cap_positive CHECK ((max_impressions IS NULL OR max_impressions > 0) AND (max_clicks IS NULL OR max_clicks > 0)),
  CONSTRAINT fk_ad_frequency_cap_ad_campaign_id FOREIGN KEY (ad_campaign_id) REFERENCES ad_campaign (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
