  UNIQUE INDEX uq_ad_frequency_cap_ad_campaign_id_ad_frequency_window_id (ad_campaign_id, ad_frequency_window_id) WHERE ad_campaign_id IS NOT NULL AND deleted_at IS NULL,
  UNIQUE INDEX uq_ad_frequency_cap_ad_group_id_ad_frequency_window_id (ad_group_id, ad_frequency_window_id) WHERE ad_group_id IS NOT NULL AND deleted_at IS NULL
);
