  CONSTRAINT ck_ad_approval_request_one_subject CHECK ((CASE WHEN ad_campaign_id IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN ad_creative_id IS NOT NULL THEN 1 ELSE 0 END) + (CASE WHEN sponsored_job_id IS NOT NULL THEN 1 ELSE 0 END) = 1),
  CONSTRAINT ck_ad_approval_request_open_state CHECK (is_open = (decided_at IS NULL)),
  CONSTRAINT ck_ad_approval_request_decided_order CHECK (decided_at IS NULL OR decided_at >= submitted_at),
  CONSTRAINT fk_ad_approval_request_ad_account_id FOREIGN KEY (ad_account_id) REFERENCES ad_account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
