  CONSTRAINT fk_ad_approval_request_ad_campaign_id FOREIGN KEY (ad_campaign_id) REFERENCES ad_campaign (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_approval_request_final_ad_approval_decision_kind_id FOREIGN KEY (final_ad_approval_decision_kind_id) REFERENCES ad_approval_decision_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_approval_request_submitted_by_app_user_id FOREIGN KEY (submitted_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_ad_approval_request_ad_campaign_id_open (ad_campaign_id) WHERE is_open AND ad_campaign_id IS NOT NULL,
  UNIQUE INDEX uq_ad_approval_request_ad_creative_id_open (ad_creative_id) WHERE is_open AND ad_creative_id IS NOT NULL,
  UNIQUE INDEX uq_ad_approval_request_sponsored_job_id_open (sponsored_job_id) WHERE is_open AND sponsored_job_id IS NOT NULL,
  INDEX idx_ad_approval_request_ad_account_id_submitted_at (ad_account_id, submitted_at DESC),
  INDEX idx_ad_approval_request_ad_approval_workflow_id_current_step_no (ad_approval_workflow_id, current_step_no) WHERE is_open,
  INDEX idx_ad_approval_request_submitted_by_app_user_id (submitted_by_app_user_id)
);
