  period_end_at TIMESTAMPTZ NOT NULL,
  spend_amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  credit_rate DECIMAL(18,6),
  credits_debited INT8,
  wallet_ledger_entry_id UUID,
