CREATE TABLE IF NOT EXISTS ad_budget_ledger (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  ad_account_id UUID NOT NULL,
  ad_campaign_id UUID NOT NULL,
  sponsored_job_id UUID,
  sequence_no INT8 NOT NULL,
  prev_sequence_no INT8,
  ad_ledger_entry_type_id UUID NOT NULL,
  amount_delta DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  spent_after DECIMAL(18,4) NOT NULL,
  usage_hour_at TIMESTAMPTZ,
  idempotency_key STRING(120) NOT NULL,
  reverses_ad_budget_ledger_id UUID,
  source_ad_performance_hourly_id UUID,
  prev_hash BYTES,
  row_hash BYTES NOT NULL,
  CONSTRAINT pk_ad_budget_ledger PRIMARY KEY (id),
  CONSTRAINT uq_ad_budget_ledger_ad_campaign_id_sequence_no UNIQUE (ad_campaign_id, sequence_no),
  CONSTRAINT uq_ad_budget_ledger_idempotency_key UNIQUE (idempotency_key),
  CONSTRAINT ck_ad_budget_ledger_first_or_prev CHECK ((sequence_no = 1 AND prev_sequence_no IS NULL) OR (sequence_no > 1 AND prev_sequence_no = sequence_no - 1)),
  CONSTRAINT ck_ad_budget_ledger_spent_nonneg CHECK (spent_after >= 0),
  CONSTRAINT ck_ad_budget_ledger_hash_len CHECK (octet_length(row_hash) = 32),
  CONSTRAINT fk_ad_budget_ledger_ad_account_id FOREIGN KEY (ad_account_id) REFERENCES ad_account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_budget_ledger_ad_campaign_id FOREIGN KEY (ad_campaign_id) REFERENCES ad_campaign (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_budget_ledger_ad_ledger_entry_type_id FOREIGN KEY (ad_ledger_entry_type_id) REFERENCES ad_ledger_entry_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_budget_ledger_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_budget_ledger_reverses_ad_budget_ledger_id FOREIGN KEY (reverses_ad_budget_ledger_id) REFERENCES ad_budget_ledger (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_budget_ledger_ad_campaign_id_prev_sequence_no FOREIGN KEY (ad_campaign_id, prev_sequence_no) REFERENCES ad_budget_ledger (ad_campaign_id, sequence_no) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_ad_budget_ledger_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_ad_budget_ledger_ad_account_id_created_at (ad_account_id, created_at DESC),
  UNIQUE INDEX uq_ad_budget_ledger_reverses_ad_budget_ledger_id (reverses_ad_budget_ledger_id) WHERE reverses_ad_budget_ledger_id IS NOT NULL,
  INDEX idx_ad_budget_ledger_sponsored_job_id (sponsored_job_id) WHERE sponsored_job_id IS NOT NULL,
  INDEX idx_ad_budget_ledger_source_ad_performance_hourly_id (source_ad_performance_hourly_id) WHERE source_ad_performance_hourly_id IS NOT NULL
);
