CREATE TABLE IF NOT EXISTS ad_creative_quality_score (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  ad_creative_id UUID NOT NULL,
  ad_placement_id UUID NOT NULL,
  expected_ctr_ratio DECIMAL(6,5) NOT NULL,
  relevance_pct DECIMAL(5,2) NOT NULL,
  landing_quality_pct DECIMAL(5,2) NOT NULL,
  quality_score INT2 NOT NULL,
  model_version STRING(50) NOT NULL,
  computed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_ad_creative_quality_score PRIMARY KEY (id),
  CONSTRAINT uq_ad_creative_quality_score_ad_creative_id_ad_placement_id UNIQUE (ad_creative_id, ad_placement_id),
  CONSTRAINT ck_ad_creative_quality_score_ctr_range CHECK (expected_ctr_ratio >= 0 AND expected_ctr_ratio <= 1),
  CONSTRAINT ck_ad_creative_quality_score_score_range CHECK (quality_score BETWEEN 1 AND 10),
  CONSTRAINT ck_ad_creative_quality_score_relevance_pct_range CHECK (relevance_pct >= 0 AND relevance_pct <= 100),
  CONSTRAINT ck_ad_creative_quality_score_landing_quality_pct_range CHECK (landing_quality_pct >= 0 AND landing_quality_pct <= 100),
  CONSTRAINT fk_ad_creative_quality_score_ad_creative_id FOREIGN KEY (ad_creative_id) REFERENCES ad_creative (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_creative_quality_score_ad_placement_id FOREIGN KEY (ad_placement_id) REFERENCES ad_placement (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
