  CONSTRAINT uq_ad_invalid_traffic_adjustment_credit_ad_budget_ledger_id UNIQUE (credit_ad_budget_ledger_id),
  CONSTRAINT ck_ad_invalid_traffic_adjustment_window CHECK (window_end_at > window_start_at),
  CONSTRAINT ck_ad_invalid_traffic_adjustment_amounts CHECK (credit_amount >= 0 AND invalid_impressions >= 0 AND invalid_clicks >= 0),
  CONSTRAINT fk_ad_invalid_traffic_adjustment_ad_campaign_id FOREIGN KEY (ad_campaign_id) REFERENCES ad_campaign (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_invalid_traffic_adjustment_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_invalid_traffic_adjustment_credit_ad_budget_ledger_id FOREIGN KEY (credit_ad_budget_ledger_id) REFERENCES ad_budget_ledger (id) ON DELETE RESTRICT ON UPDATE RESTRICT
);
