  CONSTRAINT fk_ad_invoice_line_link_ad_account_id FOREIGN KEY (ad_account_id) REFERENCES ad_account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_invoice_line_link_ad_billing_event_id FOREIGN KEY (ad_billing_event_id) REFERENCES ad_billing_event (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
