CREATE TABLE IF NOT EXISTS ad_performance_daily (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  ad_account_id UUID NOT NULL,
  ad_campaign_id UUID NOT NULL,
  ad_group_id UUID NOT NULL,
  ad_creative_id UUID NOT NULL,
  sponsored_job_id UUID,
  ad_placement_id UUID NOT NULL,
  performance_date DATE NOT NULL,
  impressions INT8 NOT NULL DEFAULT 0,
  viewable_impressions INT8 NOT NULL DEFAULT 0,
  clicks INT8 NOT NULL DEFAULT 0,
  conversions INT8 NOT NULL DEFAULT 0,
  spend_amount DECIMAL(18,6) NOT NULL DEFAULT 0,
  currency_id UUID NOT NULL,
  invalid_impressions INT8 NOT NULL DEFAULT 0,
  invalid_clicks INT8 NOT NULL DEFAULT 0,
  invalid_spend_amount DECIMAL(18,6) NOT NULL DEFAULT 0,
  is_final BOOL NOT NULL DEFAULT false,
  computed_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_ad_performance_daily PRIMARY KEY (id),
  CONSTRAINT uq_ad_performance_daily_ad_creative_id_ad_placement_id_performance_date UNIQUE (ad_creative_id, ad_placement_id, performance_date),
  CONSTRAINT ck_ad_performance_daily_counts_nonneg CHECK (impressions >= 0 AND viewable_impressions <= impressions AND clicks >= 0 AND conversions >= 0 AND spend_amount >= 0 AND invalid_impressions >= 0 AND invalid_clicks >= 0 AND invalid_spend_amount >= 0),
  CONSTRAINT fk_ad_performance_daily_ad_account_id FOREIGN KEY (ad_account_id) REFERENCES ad_account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_daily_ad_campaign_id FOREIGN KEY (ad_campaign_id) REFERENCES ad_campaign (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_daily_ad_group_id FOREIGN KEY (ad_group_id) REFERENCES ad_group (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_daily_ad_creative_id FOREIGN KEY (ad_creative_id) REFERENCES ad_creative (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_daily_ad_placement_id FOREIGN KEY (ad_placement_id) REFERENCES ad_placement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_daily_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_ad_performance_daily_ad_account_id_performance_date (ad_account_id, performance_date DESC),
  INDEX idx_ad_performance_daily_ad_campaign_id_performance_date (ad_campaign_id, performance_date DESC),
  INDEX idx_ad_performance_daily_ad_group_id_performance_date (ad_group_id, performance_date DESC),
  INDEX idx_ad_performance_daily_sponsored_job_id_performance_date (sponsored_job_id, performance_date DESC) WHERE sponsored_job_id IS NOT NULL,
  INDEX idx_ad_performance_daily_performance_date (performance_date) USING HASH WITH (bucket_count = 8)
);
