CREATE TABLE IF NOT EXISTS ad_performance_hourly (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  ad_campaign_id UUID NOT NULL,
  ad_group_id UUID NOT NULL,
  ad_creative_id UUID NOT NULL,
  ad_placement_id UUID NOT NULL,
  hour_start_at TIMESTAMPTZ NOT NULL,
  impressions INT8 NOT NULL DEFAULT 0,
  viewable_impressions INT8 NOT NULL DEFAULT 0,
  clicks INT8 NOT NULL DEFAULT 0,
  conversions INT8 NOT NULL DEFAULT 0,
  spend_amount DECIMAL(18,6) NOT NULL DEFAULT 0,
  currency_id UUID NOT NULL,
  invalid_impressions INT8 NOT NULL DEFAULT 0,
  invalid_clicks INT8 NOT NULL DEFAULT 0,
  invalid_spend_amount DECIMAL(18,6) NOT NULL DEFAULT 0,
  is_final BOOL NOT NULL DEFAULT false,
  rollup_run_ref STRING(64) NOT NULL,
  computed_at TIMESTAMPTZ NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_ad_performance_hourly PRIMARY KEY (id),
  CONSTRAINT uq_ad_performance_hourly_ad_creative_id_ad_placement_id_hour_start_at UNIQUE (ad_creative_id, ad_placement_id, hour_start_at),
  CONSTRAINT ck_ad_performance_hourly_counts_nonneg CHECK (impressions >= 0 AND viewable_impressions <= impressions AND clicks >= 0 AND conversions >= 0 AND spend_amount >= 0 AND invalid_impressions >= 0 AND invalid_clicks >= 0 AND invalid_spend_amount >= 0),
  CONSTRAINT ck_ad_performance_hourly_hour_aligned CHECK (date_trunc('hour', hour_start_at) = hour_start_at),
  CONSTRAINT fk_ad_performance_hourly_ad_campaign_id FOREIGN KEY (ad_campaign_id) REFERENCES ad_campaign (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_hourly_ad_group_id FOREIGN KEY (ad_group_id) REFERENCES ad_group (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_hourly_ad_creative_id FOREIGN KEY (ad_creative_id) REFERENCES ad_creative (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_hourly_ad_placement_id FOREIGN KEY (ad_placement_id) REFERENCES ad_placement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_ad_performance_hourly_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_ad_performance_hourly_hour_start_at (hour_start_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_ad_performance_hourly_ad_campaign_id_hour_start_at (ad_campaign_id, hour_start_at),
  INDEX idx_ad_performance_hourly_ad_group_id_hour_start_at (ad_group_id, hour_start_at)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
