CREATE TABLE IF NOT EXISTS employer_branding_purchase (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  ad_account_id UUID NOT NULL,
  employer_branding_package_id UUID NOT NULL,
  employer_branding_purchase_status_id UUID NOT NULL,
  price_paid_amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  starts_at TIMESTAMPTZ NOT NULL,
  ends_at TIMESTAMPTZ NOT NULL,
  wallet_ledger_entry_id UUID,
  invoice_line_id UUID,
  idempotency_key STRING(120) NOT NULL,
  CONSTRAINT pk_employer_branding_purchase PRIMARY KEY (id),
  CONSTRAINT uq_employer_branding_purchase_idempotency_key UNIQUE (idempotency_key),
  CONSTRAINT ck_employer_branding_purchase_window CHECK (ends_at >= starts_at),
  CONSTRAINT ck_employer_branding_purchase_price CHECK (price_paid_amount >= 0),
  CONSTRAINT fk_employer_branding_purchase_ad_account_id FOREIGN KEY (ad_account_id) REFERENCES ad_account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_employer_branding_purchase_employer_branding_package_id FOREIGN KEY (employer_branding_package_id) REFERENCES employer_branding_package (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_employer_branding_purchase_employer_branding_purchase_status_id FOREIGN KEY (employer_branding_purchase_status_id) REFERENCES employer_branding_purchase_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_employer_branding_purchase_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_employer_branding_purchase_wallet_ledger_entry_id FOREIGN KEY (wallet_ledger_entry_id) REFERENCES wallet_ledger_entry (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_employer_branding_purchase_invoice_line_id FOREIGN KEY (invoice_line_id) REFERENCES invoice_line (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_employer_branding_purchase_ad_account_id_starts_at (ad_account_id, starts_at DESC),
  INDEX idx_employer_branding_purchase_employer_branding_package_id (employer_branding_package_id),
  UNIQUE INDEX uq_employer_branding_purchase_wallet_ledger_entry_id (wallet_ledger_entry_id) WHERE wallet_ledger_entry_id IS NOT NULL AND deleted_at IS NULL,
  INDEX idx_employer_branding_purchase_invoice_line_id (invoice_line_id) WHERE invoice_line_id IS NOT NULL
);
