CREATE TABLE IF NOT EXISTS sponsored_job (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  ad_account_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  ad_campaign_id UUID NOT NULL,
  ad_group_id UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  job_boost_id UUID,
  ad_entity_status_id UUID NOT NULL,
  ad_review_status_id UUID NOT NULL,
  ad_budget_type_id UUID,
  budget_amount DECIMAL(18,4),
  currency_id UUID,
  ad_bid_strategy_id UUID,
  bid_amount DECIMAL(18,4),
  cpa_target_amount DECIMAL(18,4),
  max_applications INT4,
  promoted_headline STRING(200),
  starts_at TIMESTAMPTZ NOT NULL,
  ends_at TIMESTAMPTZ,
  impressions_total INT8 NOT NULL DEFAULT 0,
  clicks_total INT8 NOT NULL DEFAULT 0,
  applications_total INT8 NOT NULL DEFAULT 0,
  spent_amount DECIMAL(18,4) NOT NULL DEFAULT 0,
  CONSTRAINT pk_sponsored_job PRIMARY KEY (id),
  CONSTRAINT ck_sponsored_job_window CHECK (ends_at IS NULL OR ends_at >= starts_at),
  CONSTRAINT ck_sponsored_job_amounts CHECK ((budget_amount IS NULL OR budget_amount > 0) AND (bid_amount IS NULL OR bid_amount > 0) AND (cpa_target_amount IS NULL OR cpa_target_amount > 0) AND spent_amount >= 0),
  CONSTRAINT ck_sponsored_job_money_companion CHECK ((budget_amount IS NULL AND bid_amount IS NULL AND cpa_target_amount IS NULL) OR currency_id IS NOT NULL),
  CONSTRAINT ck_sponsored_job_counters CHECK (impressions_total >= 0 AND clicks_total >= 0 AND applications_total >= 0 AND (max_applications IS NULL OR max_applications > 0)),
  CONSTRAINT fk_sponsored_job_ad_account_id FOREIGN KEY (ad_account_id) REFERENCES ad_account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_campaign_id FOREIGN KEY (ad_campaign_id) REFERENCES ad_campaign (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_group_id FOREIGN KEY (ad_group_id) REFERENCES ad_group (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_job_boost_id FOREIGN KEY (job_boost_id) REFERENCES job_boost (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_entity_status_id FOREIGN KEY (ad_entity_status_id) REFERENCES ad_entity_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_review_status_id FOREIGN KEY (ad_review_status_id) REFERENCES ad_review_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_budget_type_id FOREIGN KEY (ad_budget_type_id) REFERENCES ad_budget_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_bid_strategy_id FOREIGN KEY (ad_bid_strategy_id) REFERENCES ad_bid_strategy (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_account_id_organisation_id FOREIGN KEY (ad_account_id, organisation_id) REFERENCES ad_account (id, organisation_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_organisation_id_job_requirement_id FOREIGN KEY (organisation_id, job_requirement_id) REFERENCES job_requirement (organisation_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_campaign_id_ad_account_id FOREIGN KEY (ad_campaign_id, ad_account_id) REFERENCES ad_campaign (id, ad_account_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sponsored_job_ad_group_id_ad_campaign_id FOREIGN KEY (ad_group_id, ad_campaign_id) REFERENCES ad_group (id, ad_campaign_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_sponsored_job_ad_group_id_job_requirement_id (ad_group_id, job_requirement_id) WHERE deleted_at IS NULL,
  INDEX idx_sponsored_job_organisation_id_job_requirement_id (organisation_id, job_requirement_id),
  INDEX idx_sponsored_job_ad_account_id_ad_entity_status_id (ad_account_id, ad_entity_status_id),
  INDEX idx_sponsored_job_ad_campaign_id_ends_at (ad_campaign_id, ends_at),
  INDEX idx_sponsored_job_job_boost_id (job_boost_id) WHERE job_boost_id IS NOT NULL,
  INDEX idx_sponsored_job_ad_entity_status_id_job_requirement_id (ad_entity_status_id, job_requirement_id),
  INDEX idx_sponsored_job_job_requirement_id (job_requirement_id)
);
